add('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>Hero Football Manager — Six-season playtest report</title><style>'''+css+'''</style></head><body>
<header id="top" class="wrap"><div class="topline">Hero Football Manager <small>Playtest report · 7 September 2026 · build 822e306a</small></div><h1>Bugs and issues</h1><p class="intro lead">The complete issue list comes first. Open any item for the evidence, impact, proposed fix, and a way to verify it.</p><p class="reading-guide">30 findings from one six-season Chairman career. “Bug” means observed incorrect behavior. Balance and clarity items are recommendations, not claims of broken code. 13 findings have local fixes or clearer text. Three findings are corrected or qualified. Five remain unproven or unresolved. Ten need a design choice; one of those already has clearer fire text. Current status appears beside each finding and in its CSV export. Nothing is published.</p></header>
<nav class="nav" aria-label="Report sections"><div class="wrap"><a href="#top">Issues</a><a href="#decisions">Your choices</a><a href="#verdict">Verdict</a><a href="#seasons">Each season</a><a href="#balance">Balance</a><a href="#fun">Fun and friction</a><a href="#recommendations">Fix / keep</a><a href="#evidence">Evidence</a></div></nav>
<main class="wrap"><section class="bug-section" aria-label="Complete bugs and issues list"><div class="toolbar"><label class="search">Search findings<input id="issue-search" type="search" placeholder="Try licenses, crash, training…" autocomplete="off"></label><label>Type<select id="issue-kind"><option value="all">All types</option>''')
for kind in sorted(set(i['kind'] for i in issues)):add(f'<option>{esc(kind)}</option>')
add('''</select></label><label>Priority<select id="issue-priority"><option value="all">All priorities</option><option>High</option><option>Medium</option><option>Low</option></select></label><button id="expand-issues" class="subtle">Expand all</button><button id="reset-filters" class="subtle">Reset</button><button id="export-issues" class="subtle">Export issue CSV</button></div><p id="issue-count" class="issue-count" aria-live="polite">Showing all 30 findings. Priority reflects impact in this run, not an engineering estimate.</p><div id="issues">''')
