add('''<script>
'use strict';
const report=JSON.parse(document.getElementById('report-data').textContent);
const issueNodes=[...document.querySelectorAll('.issue')];
const search=document.getElementById('issue-search'),kind=document.getElementById('issue-kind'),priority=document.getElementById('issue-priority');
function applyFilters(){const q=search.value.trim().toLowerCase();let count=0;issueNodes.forEach(node=>{node.hidden=!(node.textContent.toLowerCase().includes(q)&&(kind.value==='all'||node.dataset.kind===kind.value)&&(priority.value==='all'||node.dataset.priority===priority.value));if(!node.hidden)count++;});document.getElementById('issue-count').textContent=`Showing ${count} of ${issueNodes.length} findings. Priority reflects impact in this run, not an engineering estimate.`;document.getElementById('no-issues').hidden=count!==0;updateExpandButton();}
search.addEventListener('input',applyFilters);kind.addEventListener('change',applyFilters);priority.addEventListener('change',applyFilters);
document.getElementById('reset-filters').addEventListener('click',()=>{search.value='';kind.value='all';priority.value='all';applyFilters();});
const expand=document.getElementById('expand-issues');expand.addEventListener('click',()=>{const visible=issueNodes.filter(n=>!n.hidden);const open=visible.some(n=>!n.open);visible.forEach(n=>n.open=open);expand.textContent=open?'Collapse all':'Expand all';});
function updateExpandButton(){const visible=issueNodes.filter(n=>!n.hidden);expand.disabled=visible.length===0;expand.textContent=visible.length&&visible.every(n=>n.open)?'Collapse all':'Expand all';}
issueNodes.forEach(n=>n.addEventListener('toggle',updateExpandButton));
function selectSeason(value){document.querySelectorAll('[data-season-panel]').forEach(n=>n.hidden=value!=='all'&&n.dataset.seasonPanel!==value);document.querySelectorAll('[data-season]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.season===value)));document.getElementById('season-status').textContent=value==='all'?'Showing all six seasons.':`Showing Season ${value}. Choose All seasons to restore the full report.`;}
document.querySelectorAll('[data-season]').forEach(b=>b.addEventListener('click',()=>selectSeason(b.dataset.season)));
function revealHash(){const target=document.getElementById(location.hash.slice(1));if(!target)return;if(target.classList.contains('issue')){search.value='';kind.value='all';priority.value='all';applyFilters();target.open=true;}if(target.dataset.seasonPanel)selectSeason('all');requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));}
window.addEventListener('hashchange',revealHash);document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(a&&a.getAttribute('href')===location.hash)revealHash();});if(location.hash)revealHash();
function csvValue(v){return '"'+String(v??'').replaceAll('"','""')+'"';}
function issuesCSV(){const fields=['id','priority','kind','status','resolution','title','where','evidence','impact','fix','test','confidence'];return [fields.join(','),...report.issues.map(i=>fields.map(k=>csvValue(i[k])).join(','))].join('\\r\\n');}
document.getElementById('export-issues').addEventListener('click',()=>{const blob=new Blob(['\\uFEFF'+issuesCSV()],{type:'text/csv;charset=utf-8;'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='hero-football-manager-playtest-issues.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);});
let printState=null;
window.addEventListener('beforeprint',()=>{if(printState)return;printState=[...document.querySelectorAll('details,[data-season-panel]')].map(n=>({node:n,open:n.open,hidden:n.hidden}));printState.forEach(x=>{x.node.hidden=false;if(x.node.tagName==='DETAILS')x.node.open=true;});document.getElementById('issue-count').textContent='All 30 findings are included in this print view.';});
window.addEventListener('afterprint',()=>{if(!printState)return;printState.forEach(x=>{x.node.hidden=x.hidden;if(x.node.tagName==='DETAILS')x.node.open=x.open;});printState=null;applyFilters();});
document.getElementById('print-report').addEventListener('click',()=>window.print());
</script></body></html>''')
(OUT/'hero-football-manager-playtest-report.html').write_text(''.join(parts))
print(OUT/'hero-football-manager-playtest-report.html')
print('Findings:',len(issues),'Seasons:',len(seasons),'Words:',len(''.join(parts).split()))
